package java.util.function;
public interface IntUnaryOperator { int applyAsInt(int value); default IntUnaryOperator compose(final IntUnaryOperator p){java.util.Objects.requireNonNull(p);return new IntUnaryOperator(){public int applyAsInt(int v){return IntUnaryOperator.this.applyAsInt(p.applyAsInt(v));}};} default IntUnaryOperator andThen(final IntUnaryOperator p){java.util.Objects.requireNonNull(p);return new IntUnaryOperator(){public int applyAsInt(int v){return p.applyAsInt(IntUnaryOperator.this.applyAsInt(v));}};} static IntUnaryOperator identity(){return new IntUnaryOperator(){public int applyAsInt(int v){return v;}};} }
